// Repro: obligations_ledger_presentation.dart strip order vs
// surplus-tail + aged-tail combination (issue #2384 review check).
final _surplusTail = RegExp(
  r'\s*… and \d+ more open obligations(?:\s*\([^)]*\))?\s*$',
);
final _agedTail = RegExp(
  r'\s*… and (\d+) aged obligations — run ledger reconciliation\s*$',
);
final _technicalTail = RegExp(r'\s*\(id\s+[^)]+,\s*record\s+[^)]+\)\s*$');

String currentOrder(String s) => s
    .replaceFirst(_surplusTail, '')
    .replaceFirst(_agedTail, '')
    .replaceFirst(_technicalTail, '')
    .trim();

String reordered(String s) => s
    .replaceFirst(_agedTail, '')
    .replaceFirst(_surplusTail, '')
    .replaceFirst(_technicalTail, '')
    .trim();

void scenario(String name, String sub) {
  print('--- $name');
  print('current : [${currentOrder(sub)}]');
  print('reorder : [${reordered(sub)}]');
}

void main() {
  // Case A: aged only (this PR's tested case — must stay clean).
  scenario(
    'aged only',
    'TASK_A (id 01-a, record r1)\n'
        '… and 3 aged obligations — run ledger reconciliation\n',
  );
  // Case B: surplus + aged (open > 12 AND stale >= 1) + closed entries.
  scenario(
    'surplus + aged + closed',
    'TASK_12 (id 12-c, record r12)\n'
        '… and 5 more open obligations (read the ledger record for the full list)\n'
        '… and 3 aged obligations — run ledger reconciliation\n',
  );
  // Case C: surplus + aged, no closed entries (budget ate them).
  scenario(
    'surplus + aged only',
    'TASK_12 (id 12-c, record r12)\n'
        '… and 5 more open obligations (read the ledger record for the full list)\n'
        '… and 3 aged obligations — run ledger reconciliation\n',
  );
}

